import { FileText, Search } from 'lucide-react';
import { resolveAssetUrl } from '../../config/loadConfig';
import type { ResourceConfig } from '../../config/schema';
import { prefetchResourceViewer } from '../../shared/prefetch';
import { ResourceViewer } from './ResourceViewer';
import { cardVisual, splitTitle } from './resourceGroups';
import { kindFilters, useArchiveList, views } from './useArchiveList';

/**
 * 列表卡片：**缩略图 + 名称**（"藏品墙"，见 docs/design-preview/archive-A.png）。
 *
 * - 图片用自身出图、视频用封面 + 时长角标、图纸没有图 → 用"纸张"占位卡（带页数角标）；
 * - 缩略图 `loading="lazy"`：一屏 6 张，只加载滚到的那几张；
 * - 标题里配置自带的「（1980 年）」渲染成灰色小字，别跟主名抢；
 * - 年代/事件/说明不再上卡片，但**仍能被搜索命中**（搜索走数据，不走 DOM）。
 */
function ResourceCard({ resource, onOpen }: { resource: ResourceConfig; onOpen(): void }) {
  const { thumb, badge } = cardVisual(resource);
  const title = splitTitle(resource.title);
  return (
    <button
      type="button"
      data-kind={resource.kind}
      onPointerEnter={() => prefetchResourceViewer(resource.kind)}
      onFocus={() => prefetchResourceViewer(resource.kind)}
      onClick={onOpen}
      aria-label={`打开${resource.title}`}
    >
      {thumb
        ? <span className="archive-thumb">{<img src={resolveAssetUrl(thumb)} alt="" loading="lazy" decoding="async" />}{badge && <em className="archive-badge">{badge}</em>}</span>
        : <span className="archive-thumb is-paper"><FileText />{badge && <em className="archive-badge">{badge}</em>}</span>}
      <strong>{title.main}{title.suffix && <span className="archive-year">{title.suffix}</span>}</strong>
    </button>
  );
}

export function ArchivePage() {
  // 全部状态与派生数据都在 useArchiveList 里（与 `?ui=next` 的新结构页共享同一份实现）。
  const { query, setQuery, kind, setKind, view, setView, resources, grouped, viewer, openResource } = useArchiveList();

  if (viewer) return <ResourceViewer {...viewer} />;

  const sections = grouped;

  return (
    <section className="archive-page">
      <header className="feature-hero compact">
        <span>KNOWLEDGE BASE</span>
        <div className="archive-hero-row">
          <h1>数字档案</h1>
          {/* 视图是"怎么排布这批资料"，放在标题行；筛选才是"看哪些资料"。 */}
          <div className="archive-view-switch" role="group" aria-label="档案视图">
            {views.map(item => (
              <button type="button" key={item.value} aria-pressed={view === item.value} className={view === item.value ? 'is-active' : undefined} onClick={() => setView(item.value)}>{item.label}</button>
            ))}
          </div>
        </div>
        <p>按类型与专辑检索</p>
      </header>
      <label className="archive-search"><Search /><span className="sr-only">搜索数字档案</span><input type="search" aria-label="搜索数字档案" value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索标题、说明或原始文件名" /></label>
      {/* 只留"文件类型"一排标签：事件类型与归属那两排已按现场要求去掉（手机上一屏放三排太挤）。 */}
      <div className="archive-controls">
        <div className="archive-filters" aria-label="档案类型">
          {kindFilters.map(filter => (
            <button type="button" key={filter.value} aria-pressed={kind === filter.value} className={kind === filter.value ? 'is-active' : undefined} onClick={() => setKind(filter.value)}>{filter.label}</button>
          ))}
        </div>
      </div>
      <div className="archive-results">
        {view === 'grid' && (
          <div className="archive-grid">
            {resources.map(resource => (
              <ResourceCard key={resource.id} resource={resource} onOpen={() => openResource(resource.id)} />
            ))}
          </div>
        )}
        {view !== 'grid' && sections.map(section => (
          <section className="archive-era" key={section.key} aria-label={section.label}>
            <header><strong>{section.label}</strong><span>{section.items.length} 项</span></header>
            {section.summary && <p>{section.summary}</p>}
            <div className="archive-grid">
              {section.items.map(resource => (
                <ResourceCard key={resource.id} resource={resource} onOpen={() => openResource(resource.id)} />
              ))}
            </div>
          </section>
        ))}
        {!resources.length && <p className="empty-state">没有匹配的档案</p>}
      </div>
    </section>
  );
}
